-- G23: deterministic safety, factuality, copyright, and risk routing.
create table public.content_risk_taxonomy(risk_key text primary key,risk_class text not null check(risk_class in('low','medium','high','prohibited')),grounding_policy text not null,review_policy text not null,active boolean not null default true,created_at timestamptz not null default now());
insert into public.content_risk_taxonomy values('default','low','claim_appropriate','automated',true,now()),('election','high','current_primary_sources','human_required',true,now()),('medical','high','current_primary_sources','human_required',true,now()),('sexual_minors','prohibited','not_applicable','reject',true,now());
create table public.candidate_factual_claims(id uuid primary key default gen_random_uuid(),candidate_id uuid not null references public.contract_generation_candidates(id) on delete restrict,claim_key text not null,claim_text text not null,claim_kind text not null check(claim_kind in('general','numerical','time_sensitive')),source_evidence jsonb not null,grounded boolean not null,current_source boolean not null,primary_source boolean not null,created_at timestamptz not null default now(),unique(candidate_id,claim_key));
create table public.candidate_risk_results(id uuid primary key default gen_random_uuid(),candidate_id uuid not null references public.contract_generation_candidates(id) on delete restrict,decision text not null check(decision in('pass','human_review','reject')),risk_class text not null check(risk_class in('low','medium','high','prohibited')),content_mode text not null check(content_mode in('factual','fiction','fiction_with_factual_context')),sanitized_topic text,risk_signals text[] not null,moderation_flags text[] not null,copyright_analysis jsonb not null,grounding_policy text not null,reasons text[] not null,escalations text[] not null,policy_version text not null,created_at timestamptz not null default now(),unique(candidate_id,policy_version));
alter table public.content_risk_taxonomy enable row level security;alter table public.candidate_factual_claims enable row level security;alter table public.candidate_risk_results enable row level security;create policy risk_taxonomy_read on public.content_risk_taxonomy for select using(active or public.is_platform_admin());create policy factual_claims_staff_read on public.candidate_factual_claims for select using(public.is_staff());create policy risk_results_staff_read on public.candidate_risk_results for select using(public.is_staff());grant select on public.content_risk_taxonomy,public.candidate_factual_claims,public.candidate_risk_results to authenticated;
